        String strA = String.valueOf(a);
        String strB = String.valueOf(b);
        for (int i = 0; i < strA.length() && i < strB.length(); i++) {
            if (strA.charAt(i) != strB.charAt(i)) {
                return strA.charAt(i) - strB.charAt(i);
            }
        }
        return strA.length() - strB.length();
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    // Create a set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Iterate over the array and add unique elements to the set
    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
        }
    }

    // Calculate the sum of the unique elements
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (Math.sqrt(i) % 1 == 0) {
            count++;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversedWords = "";
    for (String word : words) {
        String reversedWord = new StringBuilder(word).reverse().toString();
        reversedWords += reversedWord + " ";
    }
    return reversedWords.trim();
}
